export function evaluate({inputs,time}){const u=inputs.launchSpeed,g=inputs.gravity;const T=u/g,H=u*u/(2*g);const t=Math.min(Math.max(time,0),2*T);const y=u*t-g*t*t/2;const v=u-g*t;const rel=t>=T;const yd=rel?y:H;const vd=rel?v:0;const ad=rel?-g:0;const base=360,sc=240/2.2;const Y=h=>base-h*sc;const o=[];const lanes=[['toss',20,'Toss',t<=0?'At launch':t<T-1e-9?'Rising':Math.abs(t-T)<1e-9?'At the top':t<2*T-1e-9?'Falling':'At launch height'],['drop',330,'Drop',!rel?'Held in place':t===T?'Just released':t<2*T-1e-9?'Falling together':'At launch height']];for(const [n,x,ti,st] of lanes){o.push(...sdk.panel({id:'lane.'+n,x,y:34,w:290,h:360,title:ti,state:st,role:n==='toss'?'input':'output'}));}
o.push(...sdk.gate('gate',475,Y(H)-20,{open:rel,label:'Gate'}));
const items=[['toss',165,y,v,-g],['drop',475,yd,vd,ad]];for(const [n,x,h,vv,aa] of items){o.push(sdk.circle('ball.'+n,x,Y(h),26));o.push(...sdk.vector('vec.v.'+n,{x:x-30,y:Y(h)},{value:vv,direction:'up'},{scale:12,label:'v',role:'observed'}));o.push(...sdk.vector('vec.a.'+n,{x:x+30,y:Y(h)},{value:aa,direction:'up'},{scale:4,label:'a',role:'warning'}));o.push(sdk.callout?sdk.callout(x+40,Y(h)-40,['v '+sdk.format(vv,2)+' m/s','a '+sdk.format(aa,1)+' m/s²'],{id:'callout.'+n}):null);}
const f=o.flat().filter(Boolean);return{frame:{width:640,height:420,objects:f,readouts:[{id:'tossedVelocity',value:v},{id:'tossedAcceleration',value:-g},{id:'dropVelocity',value:vd},{id:'dropAcceleration',value:ad}]},quantities:{launchSpeed:u,gravity:g,apexTime:T,apexHeight:H,tossedVelocity:v,tossedAcceleration:-g,tossedHeight:y,dropVelocity:vd,dropAcceleration:ad,dropHeight:yd}};}
